{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C52"],
      "claim": "Metronidazole, which shares the same 2-methyl-5-nitroimidazole core as the query, has an absolute oral bioavailability of 95% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Tinidazole, a close 5-nitroimidazole analogue, has systemic oral availability of 96–97% in humans with negligible first-pass extraction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Secnidazole, another 5-nitroimidazole analogue, shows mean absolute oral bioavailability of 100% (±26%) after oral administration in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Levornidazole, a chiral 5-nitroimidazole analogue, has absolute oral bioavailability of 98.3% ± 7.6% in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Ornidazole, a 5-nitroimidazole analogue, has systemic availability close to 100% after oral administration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 5-nitroimidazole ester (metronidazole benzoate-type prodrug). Its core and close structural analogues—metronidazole, tinidazole, secnidazole, ornidazole, and levornidazole—consistently show near-complete oral absorption and high absolute bioavailability in humans. The ester is expected to be hydrolyzed to the highly bioavailable metronidazole, and no threshold-relevant evidence supports low oral bioavailability. Therefore, F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact benzoate ester in humans is available, though prodrug hydrolysis and analogue data strongly support high F.",
    "Potential variability in ester hydrolysis or formulation effects is not directly quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

